CREATE FUNCTION issue4.identity_internal(t anyelement) RETURNS TABLE ("row" anyelement) AS $$
DECLARE
query_base text;
BEGIN
query_base := format('SELECT * FROM %s ', pg_typeof(t));
RETURN QUERY EXECUTE query_base;
END $$ LANGUAGE plpgsql;

CREATE FUNCTION issue4.identity(t anyelement) RETURNS TABLE ("row" anyelement) AS $$
DECLARE
query_base text;
BEGIN
query_base := format('SELECT * FROM %s ', pg_typeof(t));
RETURN QUERY SELECT * FROM issue4.identity_internal(t);
END $$ LANGUAGE plpgsql;

